fn cmd_dashboard(config_path: &Path) -> anyhow::Result<()> {
    let config = AppConfig::load_from_path(config_path)?;
    if let Some(ref web) = config.web { if web.enabled { open_browser(&format!("http://{}" , web.listen))? } }
    else { println!("Web dashboard not enabled"); }
    Ok(())
}
